import React, {
        useState,
        useEffect,
        createContext,
        useContext
    } from "react"
import {
    checker,
    sanitizeString
} from "../utils"
import {
    useLocation,
    useOutletContext,
    useParams,
    useNavigate
} from "react-router-dom"
import { useSignals } from "@preact/signals-react/runtime"

import FuncCategory from "./Api/FuncCategory"
import Func from "./Api/Func"
import FuncPage from "./Api/FuncPage"

import { AppState } from "../index"

export default function Documentation() {
    const [windowWidth, setWindowWidth] = useState(window.innerWidth)
    const [windowHeight, setWindowHeight] = useState(window.innerHeight)

    const {
        apiPages,
        tagTypes,
        selectedTags,
        updateTags,
        searchQuery,
        updateSearch,
        tdPatch,
        apiPage
    } = useContext(AppState);
    let navigate = useNavigate()
    useSignals();

    const hash = useLocation()
    const params = useParams()
    const pathname = hash.pathname.split("/")
    const requestedPage = sanitizeString(pathname[2] || "")
    const requestedFunction = sanitizeString(pathname[3] || "")
    const pages = apiPages.value.map(page => {
        const title = page.title
        return title.toLowerCase()
    })
    const isPage = pages.includes(requestedPage)
    const page = apiPages.value.find( page => {
        const title = page.title
        return title.toLowerCase() === (isPage
            ? requestedPage
            : "script"
        )
    })
    const categories = page.categories
    const tagCategories = []
    let requestedFunctionObj = {}
    let tags = []
    let tagCounts = []
    let paramFunctionExists = false

    if (!isPage) {
        navigate("/api/script")
    }

    const noMatches = 
        <h1 
            className="white"
        >
            No matches for 
            {
                searchQuery.value !== "" 
                    ? ` "${searchQuery.value}"`
                    : ""
            }
            {
                searchQuery.value !== "" && selectedTags.value.length > 0 
                    ? " and "
                    : ""
            }
            {
                selectedTags.value.length > 0 
                    ? "selected tags" 
                    : ""
            }
        </h1>

    const categoryElements = categories.map(({ id, category, description, functions }) => {

        if (!paramFunctionExists) {
            paramFunctionExists = functions.some(func => {
                return func.name.toLowerCase() === requestedFunction.toLowerCase()
            })
        }

        if (requestedFunction !== "") {
            const filteredFunctions = functions.filter(func => {
                return func.name.toLowerCase() === requestedFunction.toLowerCase()
            })
    
            requestedFunctionObj = filteredFunctions.length > 0
                ? filteredFunctions[0]
                : requestedFunctionObj
        }

        if (selectedTags.value.length > 0 || searchQuery.value !== "") {
            functions = functions.filter(func => {
                const matchesSearch = searchQuery.value !== ""
                    ? func.name.toLowerCase().includes(searchQuery.value.toLowerCase())
                    : false

                const matchesTags = func.tags?.length > 0
                    ? checker(func.tags, selectedTags.value)
                    : false

                return matchesSearch || matchesTags
            });
        }

        // gathering tags
        functions.map(func => {
            const funcTags = func.tags
            func.patch > tdPatch && !funcTags.includes("Experimental") && funcTags.push("Experimental")
            tags = tags.concat(funcTags).filter((value, index, self) => {
                return value !== undefined ? self.indexOf(value) === index : ""
            })

            return ""
        })

        // gathering tag counts for each tag
        functions.map(func => {
            (func.tags.length && (selectedTags.value.length === 0 || selectedTags.value.every(value => func.tags.includes(value)))) && func.tags.map(tag => {
                tagCounts[tag] = (tagCounts[tag] || 0) + 1

                return ""
            })

            return ""
        })

        if (functions.length > 0) {
            return (
                <FuncCategory
                    key={id}
                    name={category}
                    description={description}
                    functions={functions}
                    updateTags={updateTags}
                    windowWidth={windowWidth}
                    windowHeight={windowHeight}
                    page={requestedPage}
                    link={page.link}
                    expLink={page.expLink}
                    section={page.title}
                    type={page.type}
                />
            )
        }

        return false

    }).filter(element => element !== false)

    /*console.log(requestedFunction + " " + paramFunctionExists)*/

    tags.sort()
    tagTypes.value.sort((a, b) => a.name > b.name)

    let funcPage = ""

    if (paramFunctionExists) {
        const functionObj = categories
            .map(category => category.functions)
            .flat()
            .find(func => func.name.toLowerCase() === requestedFunction.toLowerCase());

        if (requestedFunction !== functionObj.name) {
            navigate(`/api/${requestedPage}/${functionObj.name}`)
        }

        funcPage = (
            windowWidth > windowHeight
            ? <FuncPage
                { ...functionObj }
                isPopup={true}
                page={requestedPage}
                link={page.link}
                expLink={page.expLink}
                section={page.title}
            />
            : <Func
                { ...functionObj }
                isPopup={true}
                page={requestedPage}
                link={page.link}
                expLink={page.expLink}
                section={page.title}
             />
        )
    } else if (searchQuery.value !== requestedFunction) {
        searchQuery.value = searchQuery.value !== ""
            ? sanitizeString(searchQuery.value)
            : requestedFunction
    }

    /*const tagElements = tags.map(tag => {
        const index = selectedTags.value.indexOf(tag)
        const selected = index > -1
        const tagCount = tagCounts[tag]
        const matches = tagCount > 0
        const styled = { color: `${matches ? "limegreen" : "red"}` }
        return (
            tagCount > 0
            ? <span
                className={`func--prev`}
                onClick={() => updateTags(tag)}
            >
                <span className={`${selected ? "red" : ""}`} >{tag}</span>
                <span className="tag--count" >{tagCount || 0}</span>
            </span>
            : ""
        )
    })*/

    const tagTypeElements = tagTypes.value.map(type => {
        const sortedTags = [...type.tags].sort();

        const elements = sortedTags
            .filter(tag => tags.includes(tag))
            .map(tag => {
                const selected = selectedTags.value.includes(tag)
                const tagCount = tagCounts[tag]

                return (
                    <div
                        className="api--tag"
                        onClick={() => updateTags(tag)}
                    >
                        <span className={`${selected ? "red" : ""}`} >{tag}</span>
                        <span className="api--tag-count" >{tagCount || 0}</span>
                    </div>
                )
            })
        return (
            elements.length > 0 ? (
                <>
                    <h3 className="api--tag-header white">{type.name}</h3>
                    {elements}
                </>
            ) : null
        )
    })

    const tagsStyle = {
        height: "0px"
    }

    {
        const tagHeight = 25
        const items = tags.length + tagTypes.value.length
        const maxWidth = windowWidth - 20
        const tagsPerRow = Math.ceil(maxWidth / 150)
        const rows = Math.floor(items / tagsPerRow)
        const height = rows * (tagHeight + 5) - 5
        const width = Math.min(tags.length * 150, maxWidth) - 150

        tagsStyle.height = `${height + 50}px`
    }

    const miscTagElements = tags
        .filter(tag => !tagTypes.value.some(type => type.tags.includes(tag)))
        .map(tag => {
            const tagsIndex = selectedTags.value.indexOf(tag)
            const selected = tagsIndex > -1
            const tagCount = tagCounts[tag]

            return (
                <div
                    className="api--tag"
                    onClick={() => {
                        console.log("hey")
                        updateTags(tag)
                    }}
                >
                    <span className={`${selected ? "red" : ""}`} >{tag}</span>
                    <span className="api--tag-count" >{tagCount || 0}</span>
                </div>
            )
        })

    const miscTagHeader = miscTagElements.length > 0
        ? <h3 className="api--tag-header white">
            Misc
        </h3>
        : ""

    const tagElement = <div
            className="api--tags"
            style={tagsStyle}
        >
            {tagTypeElements}
            {miscTagHeader}
            {miscTagElements}
        </div>

    const apiPageElement = (
        <div 
            className="func--background" 
            style={paramFunctionExists ? { overflow: "hidden", position: "fixed" } : {}}
        >
            {/*<h3 style={{color: "white", padding: "none", margin: "none"}}>Tag filtering:</h3>
            <div className="func--flex func--tags">
                {filterElements}
            </div>*/}
            {tagElement}
            <div>
                {categoryElements.length > 0
                    ? categoryElements
                    : noMatches}
            </div>
        </div>
    )

    useEffect(() => {
        const handleResize = () => {
            setWindowWidth(window.innerWidth);
            setWindowHeight(window.innerHeight);
        };
    
        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
        };
    }, []);

    return (
        <div>
            {paramFunctionExists
                ? funcPage
                : apiPageElement
            }
        </div>
    )
}