import { Link } from "react-router-dom"
import reactLogo from "../assets/images/react.png"
import nodeLogo from "../assets/images/node.png"
import teardownLogo from "../assets/images/td.png"

export default function Footer() {
    return (
        <footer>
            <p>Made with</p>
            <Link
                to="https://react.dev/"
                target="_blank"
                rel="noopener noreferrer"
            >
                <img
                    className="footer--logo footer--gap"
                    src={reactLogo}
                    alt="React"
                    align="middle"
                />
            </Link>
            {/*<Link 
                to="https://nodejs.org/" 
                target="_blank" 
                rel="noopener noreferrer"
            >
                <img
                    className="footer--logo" 
                    src={nodeLogo} 
                    alt="NodeJS" 
                    align="middle"
                />
            </Link>*/}
            <p>for</p>
            <Link
                to="https://teardowngame.com/"
                target="_blank"
                rel="noopener noreferrer"
            >
                <img
                    className="footer--logo"
                    src={teardownLogo}
                    alt="Teardown"
                    align="middle"
                />
            </Link>
        </footer>
    )
}